"""Real (non-offline) backends.

The ONLY place a heavy dependency is touched. Adapters call into here and, on
any :class:`BackendNotAvailable`, fall back to the offline artifact with the
error recorded in the manifest patch, so a run still completes and the reason
is auditable.

We target each tool's **documented stable surface**:

* Boltz-2   : ``boltz predict input.yaml -o dir`` (CLI; ``input_path`` is a
              positional arg; YAML job-list input is the documented format).
* Chai-1    : ``chai_lab`` import, FASTA input (documented on HF + PyPI).
* MPNN      : ``proteinmpnn --pdb-path backbone.pdb --out-folder out_dir`` —
              the entry point installed by ``pip install proteinmpnn`` (0.1.3,
              MIT). Emits ``predicted_sequence.jsonl`` with one sequence per
              line. Note: the repo's helper-script-style
              ``python -m proteinmpnn.reimpose`` does NOT exist in the pip
              package — do not call it.

Phase 2 (QM engines, all lazy, all optional):

* MACE      : ``mace-torch`` (ACEsuit/MACE, NeurIPS'22). Foundation model
              name via ``OPENSCIENCELAB_MACE_MODEL`` (default
              ``MACE-MP-0-medium``). ``ase.Atoms.calc = MACECalculator``.
* CHGNet    : ``ase.calculators.chgnet.CHGNet`` — Materials-Project-trained
              MPNN potential (arXiv 2007.12145).
* PySCF     : ``pyscf.gto.M`` + ``pyscf.dft.RKS`` — full DFT tier for small
              organics (the FEP+/CCSD(T) outer loop).

Geometry honesty note: for SMILES candidates we build a crude deterministic
2D scaffold layout (1.4 A spacing + small z jitter). That is NOT a real
conformer — any energy from it is a rank-ordering proxy, recorded as such in
the manifest patch and the artifact payload. Structure candidates
(Boltz/Chai/MPNN) carry real 3D coordinates and can be run through the same
backends directly.

That keeps us resilient to their frequent internal refactors, and every
command we run is visible in the manifest (we log the full argv on failure).
"""
from __future__ import annotations

import glob
import json
import os
import shutil
import subprocess
from typing import Any, Dict, List, Optional


class BackendNotAvailable(RuntimeError):
    """Real backend required but not usable. Adapters catch this -> offline."""


# --------------------------------------------------------------------------- #
# Device / GPU state                                                           #
# --------------------------------------------------------------------------- #
def torch_or_none():
    try:
        import torch  # type: ignore

        return torch
    except Exception:
        return None


def device() -> str:
    """Torch device string.

    ROCm exposes the CUDA device id (``"cuda"``); ``HSA_OVERRIDE_GFX_VERSION``
    handles the Strix Halo gfx1151 mapping at HSA-init. If the HSA runtime
    failed to attach, torch reports ``cuda.is_available() == False`` and we
    fall back to CPU *loudly*: the manifest patch from ``gpu_info()`` records
    why, so it's never silent. ``OPENSCIENCELAB_DEVICE`` may force
    ``cpu``/``cuda``; empty means auto.
    """
    ov = (os.environ.get("OPENSCIENCELAB_DEVICE") or "").lower()
    if ov in ("cpu", "cuda", "xpu", "mps"):
        return ov
    torch = torch_or_none()
    if torch is None:
        return "cpu"
    return "cuda" if torch.cuda.is_available() else "cpu"


def gpu_info() -> Dict[str, Any]:
    """Hardware snapshot for the manifest + the ``gpucheck`` CLI. Never raises."""
    torch = torch_or_none()
    info: Dict[str, Any] = {
        "torch": torch.__version__ if torch else None,
        "torch_hip": (
            str(torch.version.hip)
            if torch and getattr(torch.version, "hip", None)
            else None
        ),
        "torch_cuda": (
            str(torch.version.cuda)
            if torch and getattr(torch.version, "cuda", None)
            else None
        ),
        "cuda_visible": bool(torch and torch.cuda.is_available()),
        "device": device(),
        "HSA_OVERRIDE_GFX_VERSION": os.environ.get("HSA_OVERRIDE_GFX_VERSION"),
    }
    if torch and torch.cuda.is_available():
        try:
            info["device_name"] = torch.cuda.get_device_name(0)
            info["device_count"] = torch.cuda.device_count()
        except Exception:
            info["device_name"] = None
            info["device_count"] = 0
    return info


# --------------------------------------------------------------------------- #
# Boltz-2 — structure                                                          #
# --------------------------------------------------------------------------- #
def _norm_input(input_: Any) -> Dict[str, Any]:
    """Normalize ``seq``/``smi`` and ``sequence``/``smile`` to one shape."""
    if isinstance(input_, str):
        return {"name": "A", "sequence": input_}
    if isinstance(input_, dict):
        out: Dict[str, Any] = {"chains": [], "smile": None}
        if input_.get("sequence") or input_.get("seq"):
            out["chains"].append(
                {
                    "name": "A",
                    "sequence": input_.get("sequence") or input_.get("seq"),
                }
            )
        for c in input_.get("chains") or []:
            if not isinstance(c, dict):
                continue
            nc = {k: c.get(k) for k in ("name",) if c.get(k)}
            seq = c.get("sequence") or c.get("seq")
            smi = c.get("smile") or c.get("smi")
            if seq:
                nc["sequence"] = seq
            if smi:
                nc["smile"] = smi
            if nc.get("sequence") or nc.get("smile"):
                out["chains"].append(nc)
        out["smile"] = input_.get("smile") or input_.get("smi")
        return out
    raise TypeError(f"unsupported structure input type: {type(input_)!r}")


def _boltz_yaml(input_: Any, name: str) -> str:
    """Render our input (str sequence, or dict with chains + SMILES) into
    boltz's documented YAML job list."""
    import yaml  # pyyaml ships with boltz

    n = _norm_input(input_)

    job: Dict[str, Any] = {"name": name}
    proteins: List[Dict[str, str]] = []
    ligands: List[Dict[str, str]] = []

    for i, c in enumerate(n["chains"]):
        if c.get("smile"):
            ligands.append({"name": c.get("name") or f"lig{i}", "smile": c["smile"]})
        if c.get("sequence"):
            proteins.append({"name": c.get("name") or f"P{i}", "sequence": c["sequence"]})
    if n.get("smile"):
        ligands.append({"name": "lig", "smile": n["smile"]})

    if not proteins and not ligands:
        raise ValueError("no protein sequence or SMILES in input")
    if proteins:
        job["proteins"] = proteins
    if ligands:
        job["ligands"] = ligands
    return yaml.safe_dump([job], sort_keys=False)


def predict_boltz2(input_: Any, work_dir: str, name: str = "target") -> Dict[str, Any]:
    """Run ``boltz predict`` on ``input_`` into ``work_dir``.

    Returns ``{"predicted": <best CIF>, "metrics": {...}, "device": str,
    "output_root": <dir>}``. Raises :class:`BackendNotAvailable` on any failure.
    """
    os.makedirs(work_dir, exist_ok=True)
    yaml_path = os.path.join(work_dir, "input.yaml")
    with open(yaml_path, "w") as fh:
        fh.write(_boltz_yaml(input_, name))

    exe = shutil.which("boltz")
    if exe is None:
        raise BackendNotAvailable(
            "'boltz' not on PATH. In Docker it ships in the image; "
            "bare metal: pip install 'boltz>=2.0'"
        )
    cmd = [exe, "predict", yaml_path, "-o", work_dir]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
    except subprocess.TimeoutExpired as e:
        raise BackendNotAvailable("boltz predict timed out (>1h); cmd=" + " ".join(cmd)) from e
    if proc.returncode != 0:
        raise BackendNotAvailable(
            f"boltz predict exited {proc.returncode}: {proc.stderr[-2000:]}"
        )

    # boltz 2.x output: work_dir/predictions/<name>/{*_model_0.cif, confidence_*.json}
    target_dir = os.path.join(work_dir, "predictions", name)
    cifs = sorted(glob.glob(os.path.join(target_dir, "*_model_0.cif")))
    if not cifs:
        cifs = sorted(glob.glob(os.path.join(work_dir, "**", "*_model_0.cif"), recursive=True))
    if not cifs:
        raise BackendNotAvailable(
            f"boltz finished but no *_model_0.cif found under {work_dir!r}"
        )
    best = cifs[0]  # boltz ranks model_0 first

    metrics: Dict[str, float] = {}
    for conf in glob.glob(os.path.join(target_dir, "confidence_*.json")):
        try:
            with open(conf) as fh:
                for k, v in json.load(fh).items():
                    if isinstance(v, (int, float)) and not isinstance(v, bool):
                        metrics[k] = float(v)
        except Exception:
            pass
    return {
        "predicted": best,
        "metrics": metrics,
        "device": device(),
        "output_root": os.path.join(work_dir, "predictions"),
    }


# --------------------------------------------------------------------------- #
# Chai-1 — structure                                                           #
# --------------------------------------------------------------------------- #
def _chai1_fasta(input_: Any) -> str:
    n = _norm_input(input_)
    out = []
    for c in n["chains"]:
        if c.get("sequence"):
            out.append(f">{c.get('name') or 'A'}\n{c['sequence']}\n")
    if not out:
        raise ValueError("no protein sequence in input for chai1")
    return "".join(out)


def predict_chai1(input_: Any, out_dir: str) -> Dict[str, Any]:
    """Run Chai-1 ``chai_lab.chai1.run_inference`` on a FASTA.

    FASTA is chai1's documented input. We write it, call the documented API,
    then return the best PDB chai1 emitted.
    """
    os.makedirs(out_dir, exist_ok=True)
    fasta = os.path.join(out_dir, "input.fasta")
    with open(fasta, "w") as fh:
        fh.write(_chai1_fasta(input_))

    try:
        from chai_lab import chai1  # type: ignore
    except Exception as e:
        exe = shutil.which("chai1")
        if exe is None:
            raise BackendNotAvailable(
                f"chai1 not importable and no 'chai1' CLI (got {type(e).__name__})"
            ) from e
        cmd = [exe, "predict", fasta, "-o", out_dir]
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
        except subprocess.TimeoutExpired as e:
            raise BackendNotAvailable("chai1 timed out (>1h); cmd=" + " ".join(cmd)) from e
        if proc.returncode != 0:
            raise BackendNotAvailable(f"chai1 exited {proc.returncode}: {proc.stderr[-1500:]}")
        pdb = _find_best(out_dir)
        if pdb is None:
            raise BackendNotAvailable("chai1 finished but no PDB found in out_dir")
        return {"predicted": pdb, "metrics": {}, "device": device(), "output_root": out_dir}

    # Chai-1's import surface has moved across 0.4-0.7, so we try the
    # documented ``run_inference`` first, then fall through to the model
    # constructor if that surface is absent.
    try:
        kwargs: Dict[str, Any] = dict(
            device=device(),
            num_diffusion_iterations=100,
            num_trunk_iterations=1,
            checkpoint_dir=None,
        )
        pred = chai1.run_inference(fasta, out_dir=out_dir, **kwargs)
    except (AttributeError, TypeError) as e:
        raise BackendNotAvailable(
            f"chai1.run_inference signature changed ({type(e).__name__}: {e}); "
            "see chai-lab docs for the current kwarg set"
        ) from e
    except Exception as e:
        raise BackendNotAvailable(
            f"chai1 run_inference failed: {type(e).__name__}: {e}"
        ) from e

    pdb = _find_best(out_dir)
    if pdb is None:
        raise BackendNotAvailable("chai1 finished but no PDB found in out_dir")
    return {"predicted": pdb, "metrics": {}, "device": device(), "output_root": out_dir}


def _find_best(root: str) -> Optional[str]:
    """chai1 emits PDBs under out_dir/predictions/...; take the first,
    preferring anything with 'predicted' in the name."""
    peds = glob.glob(os.path.join(root, "**", "*.cif"), recursive=True)
    if not peds:
        peds = glob.glob(os.path.join(root, "**", "*.pdb"), recursive=True)
    peds.sort(key=lambda p: ("predicted" not in p.lower(), p))
    return peds[0] if peds else None


# --------------------------------------------------------------------------- #
# ProteinMPNN — design                                                         #
# --------------------------------------------------------------------------- #
def design_mpnn(backbone_pdb: str, out_dir: str, n_seqs: int = 3, seed: int = 0) -> List[Dict[str, str]]:
    """Re-impose sequences on a backbone via the proteinmpnn pip package (MIT).

    ``proteinmpnn==0.1.3`` installs a ``proteinmpnn`` entry point — NOT a
    ``python -m proteinmpnn...`` module (that module does not exist). Flags
    (documented in the PyPI description): ``--pdb-path`` /
    ``--out-folder`` / ``--num_seq_per_target`` / ``--seed`` /
    ``--temperature`` (sampling temperature). Output: a
    ``predicted_sequence.jsonl`` inside the out folder, one JSON object per
    entry with a ``"sequence"`` per chain. We collect up to ``n_seqs``
    sequences and the adapter's offline fallback tops the rest up
    deterministically when MPNN is unavailable.
    """
    if not os.path.exists(backbone_pdb):
        raise BackendNotAvailable(f"backbone PDB not found: {backbone_pdb!r}")
    exe = shutil.which("proteinmpnn")
    if exe is None:
        # fall back to "python -c 'from proteinmpnn import protein_mpnn_main; ...'"
        # is NOT documented; instead just report clearly so the offline path kicks in.
        raise BackendNotAvailable(
            "proteinmpnn entry point not on PATH; "
            "pip install proteinmpnn (>=0.1.3)"
        )
    os.makedirs(out_dir, exist_ok=True)
    # MPNN's seed default (0) means "random seed" — always pin one for us.
    cmd = [
        exe,
        "--pdb-path", backbone_pdb,
        "--out-folder", out_dir,
        "--num_seq_per_target", str(max(1, n_seqs)),
        "--seed", str(seed if seed else 1337),
    ]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=1800)
    except subprocess.TimeoutExpired as e:
        raise BackendNotAvailable("proteinmpnn timed out (>30m)") from e
    if proc.returncode != 0:
        raise BackendNotAvailable(
            f"proteinmpnn exited {proc.returncode}: {proc.stderr[-2000:]}"
        )
    # Output contract: "<out>/predicted_sequence.jsonl" (one JSON per line,
    # "sequence" per chain keyed by chain id). Scan rather than assume layout.
    lines: List[Dict[str, Any]] = []
    for name in ("predicted_sequence.jsonl",):
        for p in glob.glob(os.path.join(out_dir, "**", name), recursive=True):
            with open(p) as fh:
                for ln in fh:
                    ln = ln.strip()
                    if ln:
                        try:
                            lines.append(json.loads(ln))
                        except Exception:
                            continue
            break
    if not lines:
        raise BackendNotAvailable(
            f"proteinmpnn finished but no predicted_sequence.jsonl under {out_dir}"
        )
    out: List[Dict[str, str]] = []
    for i, d in enumerate(lines[: max(1, n_seqs)]):
        seqs = d.get("sequences") or d.get("sequence") or d
        if isinstance(seqs, dict):
            # per-chain dict {"A": "MSK...", "B": "..."} ; take the biggest chain
            best = max(seqs.items(), key=lambda kv: len(kv[1]))
            s = best[1]
        else:
            s = str(seqs)
        out.append({"name": f"MPNN-{i:03d}", "seq": s, "source": "proteinmpnn"})
    return out


# --------------------------------------------------------------------------- #
# Phase 2 — QM engines (MACE / CHGNet / PySCF)                                #
# --------------------------------------------------------------------------- #
_SYMBOL_TO_Z = {
    "C": 6, "N": 7, "O": 8, "F": 9, "P": 15, "S": 16, "Cl": 17,
    "Br": 35, "B": 5, "I": 53, "Li": 3, "Na": 11, "K": 19, "Mg": 12,
    "Ca": 20, "Zn": 30, "Mn": 25, "Fe": 26, "Cu": 29,
}
_HBA_ATOMS = ("O", "N", "S", "F", "Cl")


def _atom_tokens(smi: str) -> List[str]:
    """Crude SMILES tokenizer: heavy-atom symbols in order. This is the
    canonical SMILES-lite path; ``adapters.scoring`` re-exports it for
    tier-0 descriptors (no duplicated implementation anywhere else)."""
    if not smi:
        return []
    smi = (smi.replace("(", "").replace(")", "").replace("=", "")
              .replace("#", "").replace("-", "").replace("/", "").replace("\\", ""))
    out: List[str] = []
    i = 0
    smap = {"n": "N", "o": "O", "s": "S", "p": "P", "f": "F", "b": "B", "c": "C"}
    while i < len(smi):
        ch = smi[i]
        if ch.isalpha():
            if ch.isupper():
                if smi[i:i + 2] in ("Cl", "Br"):
                    out.append(smi[i:i + 2])
                    i += 2
                    continue
                out.append(ch)
            else:
                out.append(smap.get(ch, ch))
        i += 1
    return out


def element_types_of(smi: str) -> List[int]:
    """Atom numbers from a SMILES. Prefers RDKit (accurate); falls back to the
    SMILES-lite tokenizer above (no dependency)."""
    try:
        from rdkit import Chem  # type: ignore

        mol = Chem.MolFromSmiles(smi)
        if mol is not None and next(iter(mol.GetAtoms()), None) is not None:
            return [a.GetAtomicNum() for a in mol.GetAtoms()]
    except Exception:
        pass
    tokens = _atom_tokens(smi)
    if not tokens:
        raise BackendNotAvailable(f"unparseable SMILES: {smi!r}")
    return [_SYMBOL_TO_Z.get(t, 6) for t in tokens]


def scaffold_coords(numbers: List[int], seed: int = 7) -> List[List[float]]:
    """Deterministic placeholder 2D layout (1.4 A steps, small z jitter).

    NOT a conformer — energies on this are a rank-ordering proxy. Always
    prefer real structure output (Boltz-2 / Chai-1 / MPNN backbones) when
    available; pass its coordinates straight to :func:`mace_energy` /
    :func:`chgnet_energy` / :func:`pyscf_energy` instead."""
    import random

    rng = random.Random(seed)
    step = 1.4  # rough C-C bond length
    coords: List[List[float]] = []
    for i in range(len(numbers)):
        x = i * step + rng.uniform(-0.02, 0.02)
        y = 0.3 if (i % 2 == 0) else -0.3
        z = 0.05 if (i % 3 == 0) else -0.05
        coords.append([x, y, z])
    return coords


def _mace_device_str(device: Optional[str]) -> str:
    """Map our device() result onto MACE's expected string (MACE takes
    'cuda:0' style or 'cpu')."""
    if not device or device in ("cpu", "auto"):
        return "cpu"
    if device == "cuda":
        try:
            import torch
            return "cuda:0" if torch.cuda.is_available() else "cpu"
        except Exception:
            return "cuda:0"
    return device  # already specific, e.g. 'cuda:1' or 'mps'


def _mace_calc_factory(device: Optional[str] = None):
    """Build an ASE-compatible MACE calculator for the configured foundation
    model. Tries, in order:

    1. ``mace.calculators.mace_mp()`` — the documented foundation-model
       loader in mace-torch >= 0.3 (returns a ready :class:`MACECalculator`;
       pick the model via ``OPENSCIENCELAB_MACE_MODEL``).
    2. Legacy ``mace.load_model(name)`` + :class:`MACECalculator` wrap.

    Failures raise :class:`BackendNotAvailable` with the underlying cause.
    """
    dev = _mace_device_str(device)
    try:
        from mace.calculators import MACECalculator  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"mace.calculators import failed: {e}")

    name = os.environ.get("OPENSCIENCELAB_MACE_MODEL") or "MACE-MP-0-medium"

    # 1) foundation-model convenience loader: mace_mp(device=..., model_name=...)
    #    (mace-torch >= 0.3). Older builds used positional name only — fall
    #    through to the legacy path if the kwarg name doesn't match.
    try:
        from mace.calculators import mace_mp  # type: ignore

        try:
            calc = mace_mp(device=dev, model_name=name)
        except TypeError:
            try:
                calc = mace_mp(name, device=dev)
            except TypeError:
                calc = mace_mp(device=dev)
        return calc, "mace_mp"
    except Exception:
        pass

    # 2) legacy path
    try:
        import mace  # type: ignore

        model = mace.load_model(name)
        return MACECalculator(model=model, devices=dev), f"mace[{name}]"
    except Exception as e:
        raise BackendNotAvailable(f"no working MACE loader (tried mace_mp + legacy): {e}")


_MACE_CALC_CACHE: Dict[str, Any] = {}


def mace_energy(coords: List[List[float]], numbers: List[int],
                device: Optional[str] = None) -> Dict[str, Any]:
    """MACE potential energy in eV (forces included free — single ASE pass)."""
    try:
        import ase  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"ase import failed: {e}")
    key = device or "cpu"
    if key not in _MACE_CALC_CACHE:
        _MACE_CALC_CACHE[key] = _mace_calc_factory(device)
    calc, label = _MACE_CALC_CACHE[key]
    atoms = ase.Atoms(numbers=list(numbers), positions=list(coords))
    atoms.calc = calc
    try:
        energy = float(atoms.get_potential_energy())
        forces = atoms.get_forces().tolist()
    except Exception as e:
        raise BackendNotAvailable(f"MACE inference failed: {e}")
    return {"energy_eV": energy, "forces": forces, "model": label,
            "device": _mace_device_str(device)}


def mace_available() -> bool:
    try:
        import mace.calculators  # noqa: F401
        return True
    except Exception:
        return False


def chgnet_available() -> bool:
    try:
        import ase  # noqa: F401
        from ase.calculators.chgnet import CHGNet  # noqa: F401
        return True
    except Exception:
        return False


def chgnet_energy(coords: List[List[float]], numbers: List[int]) -> Dict[str, Any]:
    """CHGNet (ASE) total energy in eV + forces."""
    try:
        import ase  # type: ignore
        from ase.calculators.chgnet import CHGNet  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"CHGNet / ase import failed: {e}")
    atoms = ase.Atoms(numbers=list(numbers), positions=list(coords))
    try:
        atoms.calc = CHGNet()
        energy = float(atoms.get_total_energy())
        forces = atoms.get_forces().tolist()
    except Exception as e:
        raise BackendNotAvailable(f"CHGNet inference failed: {e}")
    return {"energy_eV": energy, "forces": forces, "model": "CHGNet", "device": "cpu"}


def pyscf_available() -> bool:
    try:
        import pyscf  # noqa: F401
        return True
    except Exception:
        return False


def pyscf_energy(numbers: List[int], coords: List[List[float]],
                 xc: Optional[str] = None, basis: str = "6-31G*") -> Dict[str, Any]:
    """PySCF total electronic energy (Hartree).

    ``xc=None`` → RHF; else RKS with that functional (default recommended for
    Tier-2 DFT is B3LYP). ``basis`` defaults to 6-31G* — the canonical
    organic-molecule DFT basis.
    """
    try:
        import pyscf  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"pyscf import failed: {e}")
    atom_arg = [
        (int(n), (float(x), float(y), float(z)))
        for n, (x, y, z) in zip(numbers, coords)
    ]
    try:
        mol = pyscf.gto.M(atom=atom_arg, unit="Angstrom", basis=basis)
        if xc:
            mf = pyscf.dft.RKS(mol, xc=xc)
        else:
            mf = pyscf.hf.RHF(mol)
        e_total = mf.kernel()
    except Exception as e:
        raise BackendNotAvailable(f"pyscf kernel failed: {e}")
    return {
        "energy_Hartree": float(e_total),
        "method": f"{'RKS/' + xc if xc else 'RHF'}/{basis}",
    }


__all__ = [
    "BackendNotAvailable",
    "device",
    "gpu_info",
    "predict_boltz2",
    "predict_chai1",
    "design_mpnn",
    # Phase 2
    "element_types_of",
    "scaffold_coords",
    "mace_available",
    "mace_energy",
    "chgnet_available",
    "chgnet_energy",
    "pyscf_available",
    "pyscf_energy",
]

"""Structure-prediction adapters.

Primary backend: Boltz-2 (MIT license). Alternate: Chai-1.
Without the backend installed (or failing at runtime), the adapter produces a
clearly-marked **offline** artifact (a deterministic placeholder) so the
pipeline contract still holds end-to-end; the failure reason is recorded in
the manifest patch. The output artifact always carries the same keys —
``pred_structures`` (list), ``metrics`` (dict), ``model``, ``input_summary``.
"""
from __future__ import annotations

import os
import random
from typing import Any, Dict

from ..base import Adapter, Artifact, Bundle
from ..backends import BackendNotAvailable, predict_boltz2, predict_chai1


def _summarize_input(input_: Any) -> Dict[str, Any]:
    if isinstance(input_, str):
        seq = input_
        return {"n_chains": 1, "total_length": len(seq), "names": ["A"]}
    if isinstance(input_, dict):
        chains = input_.get("chains") or ([{"seq": input_["seq"]}] if "seq" in input_ else [])
        total = sum(len(c.get("seq", "") or c.get("sequence", "")) for c in chains)
        if not total:
            # input had no explicit chains (e.g. {"seq": "...", "smi": "..."} with
            # non-list "chains"); fall back to the length of the top-level "seq"
            total = len(input_.get("seq", "") or input_.get("sequence", ""))
        return {
            "n_chains": max(1, len(chains)),
            "total_length": total,
            "names": [c.get("name", f"X{i}") for i, c in enumerate(chains)] or ["A"],
            "ligand_smi": input_.get("smi") or input_.get("smile"),
        }
    raise ValueError(f"unsupported structure input type: {type(input_)!r}")


class Boltz2Adapter(Adapter):
    name = "structure.boltz2"
    version = "0.0.1"

    def _exec(self, manifest, budget, input_) -> Bundle:
        summary = _summarize_input(input_)
        # Real path first; fall back to the offline placeholder on
        # missing/failing backend so a run still completes.
        try:
            backend = predict_boltz2(
                input_,
                work_dir=os.path.join(manifest.run_dir, "backends", "boltz2"),
                name=summary["names"][0],
            )
            art = Artifact(
                kind="structure",
                payload={
                    "offline": False,
                    "model": "boltz2",
                    "input_summary": summary,
                    "metrics": backend["metrics"],
                    "pred_structures": [os.path.relpath(backend["predicted"], manifest.run_dir)],
                    "device": backend["device"],
                },
            )
            return Bundle(
                artifacts=[art],
                cost={1: max(1.0, summary["total_length"] * 0.02)},
                manifest_patch={"structure_backend": "boltz2"},
            )
        except Exception as e:
            patch_note = f"boltz2-offline ({type(e).__name__}: {e})"

        # ---- offline deterministic placeholder -------------------------------
        n_residues = summary["total_length"]
        rng = random.Random(manifest.seeds.get("structure", 0) + n_residues)
        plddt = {f"{i}": round(90.0 + rng.uniform(0, 9), 1) for i in range(min(n_residues, 5))}
        art = Artifact(
            kind="structure",
            payload={
                "offline": True,
                "model": "boltz2",
                "input_summary": summary,
                "metrics": {"mean_plddt": 90.0 + rng.uniform(0, 9)},
                "pred_structures": [f"placeholder_{summary['names'][0]}_{n_residues}aa"],
            },
        )
        return Bundle(
            artifacts=[art],
            cost={1: max(1.0, n_residues * 0.02)},
            manifest_patch={"structure_backend": patch_note},
        )


class Chai1Adapter(Adapter):
    name = "structure.chai1"
    version = "0.0.1"

    def _exec(self, manifest, budget, input_) -> Bundle:
        summary = _summarize_input(input_)
        try:
            backend = predict_chai1(
                input_,
                out_dir=os.path.join(manifest.run_dir, "backends", "chai1"),
            )
            art = Artifact(
                kind="structure",
                payload={
                    "offline": False,
                    "model": "chai1",
                    "input_summary": summary,
                    "metrics": backend["metrics"],
                    "pred_structures": [os.path.relpath(backend["predicted"], manifest.run_dir)],
                    "device": backend["device"],
                },
            )
            return Bundle(
                artifacts=[art],
                cost={1: max(1.0, summary["total_length"] * 0.02)},
                manifest_patch={"structure_backend": "chai1"},
            )
        except Exception as e:
            patch_note = f"chai1-offline ({type(e).__name__}: {e})"

        art = Artifact(
            kind="structure",
            payload={
                "offline": True,
                "model": "chai1",
                "input_summary": summary,
                "metrics": {"mean_ptm": 0.18},
                "pred_structures": ["placeholder_chai1"],
            },
        )
        return Bundle(
            artifacts=[art],
            cost={1: max(1.0, summary["total_length"] * 0.02)},
            manifest_patch={"structure_backend": patch_note},
        )


class ESMFoldAdapter(Adapter):
    name = "structure.esmfold"
    version = "0.0.1"

    def _exec(self, manifest, budget, input_) -> Bundle:
        if isinstance(input_, dict) and input_.get("chains"):
            raise ValueError("ESMFold path supports a single sequence only")
        summary = _summarize_input(input_)
        art = Artifact(
            kind="structure",
            payload={
                "offline": True,
                "model": "esmfold",
                "input_summary": summary,
                "metrics": {"mean_pa": 0.85},
                "pred_structures": ["placeholder_esmfold"],
            },
        )
        return Bundle(
            artifacts=[art],
            cost={1: max(1.0, summary["total_length"] * 0.01)},
            manifest_patch={"structure_backend": "esmfold-offline"},
        )


from ..base import registry  # noqa: E402

registry.register(Boltz2Adapter())
registry.register(Chai1Adapter())
registry.register(ESMFoldAdapter())

"""Shared types, the Adapter contract, and the registry.

Design rule: every capability (structure, design, scoring, optimization) is an
:class:`Adapter`. Everything funnels through :meth:`Adapter.run`, which
charges the budget, stamps artifacts, and records the call on the run
manifest. That single choke point is what makes provenance and budgeting
trivial.

Re-exports from :mod:`.manifest` (``Budget``, ``budget_default``,
``BudgetExceeded``) so a service can import one module.
"""
from __future__ import annotations

import hashlib
import json
import time
import uuid
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional

from .manifest import Budget, BudgetExceeded, Manifest, RunDirectory, budget_default  # noqa: F401  (re-export)


def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


# --------------------------------------------------------------------------- #
# Cost model: tiered compute                                                  #
# --------------------------------------------------------------------------- #
# Higher tier = slower / more expensive, used on fewer candidates. Costs are
# abstract "units" (not $); a Budget maps them to real cost as needed.
TIER_ZERO, TIER_ONE, TIER_TWO = 0, 1, 2


# --------------------------------------------------------------------------- #
# Core data types                                                             #
# --------------------------------------------------------------------------- #
@dataclass
class Candidate:
    """A thing being scored (molecule / complex / crystal)."""

    id: str
    kind: str = "molecule"  # molecule | complex | crystal
    smi: Optional[str] = None
    pdb_id: Optional[str] = None
    seq: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Candidate":
        d = dict(d)
        d.setdefault("metadata", {})
        allowed = {k: d[k] for k in ("id", "kind", "smi", "pdb_id", "seq", "metadata") if k in d}
        return cls(**allowed)


@dataclass
class ScoreVector:
    """Named metric values for a candidate.

    Convention: **higher is better** for every key. A scoring adapter flips the
    sign of naturally "lower-better" metrics (e.g. docking energy) beforehand.
    """

    metrics: Dict[str, float] = field(default_factory=dict)
    tier: int = TIER_ZERO
    notes: Dict[str, Any] = field(default_factory=dict)

    def get(self, name: str, default: float = 0.0) -> float:
        return self.metrics.get(name, default)

    def to_dict(self) -> Dict[str, Any]:
        return {"tier": self.tier, "metrics": self.metrics, "notes": self.notes}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "ScoreVector":
        return cls(
            metrics=dict(d.get("metrics", {})),
            tier=d.get("tier", TIER_ZERO),
            notes=dict(d.get("notes", {})),
        )


@dataclass
class Artifact:
    """An immutable product of an adapter call, with a stable digest."""

    id: str = ""
    kind: str = ""  # structure | design_seqs | scores | pareto | report | ...
    service: str = ""
    service_version: str = ""
    created_at: str = ""
    payload: Dict[str, Any] = field(default_factory=dict)
    files: List[str] = field(default_factory=list)  # relative paths under run dir

    def digest(self) -> str:
        blob = json.dumps(
            {
                "id": self.id,
                "kind": self.kind,
                "service": self.service,
                "service_version": self.service_version,
                "payload": self.payload,
            },
            sort_keys=True,
            default=str,
        ).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()[:16]

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["digest"] = self.digest()
        return d


@dataclass
class Bundle:
    """What every adapter returns: artifacts, manifest patch, cost by tier."""

    artifacts: List[Artifact] = field(default_factory=list)
    manifest_patch: Dict[str, Any] = field(default_factory=dict)
    cost: Dict[int, float] = field(
        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}
    )

    def total_cost(self) -> float:
        return sum(self.cost.values())


# --------------------------------------------------------------------------- #
# Adapter contract                                                            #
# --------------------------------------------------------------------------- #
class Adapter(ABC):
    """Base class for all services.

    Subclasses set ``name`` and ``version`` and implement :meth:`_exec`.
    :meth:`run` adds the boilerplate: charging the budget, stamping artifacts,
    and recording the call against the run manifest.
    """

    name: str = "adapter"
    version: str = "0.0.1"

    @abstractmethod
    def _exec(self, manifest, budget, **inputs) -> Bundle:
        raise NotImplementedError

    def run(self, manifest, budget, **inputs) -> Bundle:
        bundle = self._exec(manifest, budget, **inputs)

        # charge the budget for each tier used (validates per-tier limits)
        if budget is not None:
            for tier, cost in bundle.cost.items():
                budget.spend(int(tier), float(cost))

        # stamp artifacts with this service's identity
        for art in bundle.artifacts:
            if not art.service:
                art.service = self.name
            if not art.service_version:
                art.service_version = self.version
            if not art.created_at:
                art.created_at = _now()
            if not art.id:
                art.id = new_id(art.kind)
            manifest.attach_artifact(art.to_dict(), list(art.files))

        # record the call (stable signature enables drift detection)
        manifest.record(
            service=self.name,
            version=self.version,
            call={k: _jsonable(v) for k, v in inputs.items()},
            cost=bundle.cost,
            artifacts=[a.id for a in bundle.artifacts],
        )
        manifest.merge_patch(bundle.manifest_patch)
        return bundle


def _jsonable(v: Any) -> Any:
    if isinstance(v, dict):
        return {str(k): _jsonable(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [_jsonable(x) for x in v]
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    if isinstance(v, Candidate):
        return v.to_dict()
    if isinstance(v, ScoreVector):
        return v.to_dict()
    return repr(v)


def new_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:10]}"


# --------------------------------------------------------------------------- #
# Registry                                                                    #
# --------------------------------------------------------------------------- #
class _Registry:
    """Name -> Adapter instance. Adapters self-register on import."""

    def __init__(self) -> None:
        self._adapters: Dict[str, Adapter] = {}

    def register(self, adapter: Adapter) -> None:
        existing = self._adapters.get(adapter.name)
        if existing is not None and existing.version != adapter.version:
            raise ValueError(
                f"adapter {adapter.name!r} already registered at "
                f"{existing.version!r}; refusing to overwrite"
            )
        self._adapters[adapter.name] = adapter

    def get(self, name: str) -> Adapter:
        if name not in self._adapters:
            raise KeyError(
                f"adapter {name!r} not registered. "
                f"Available: {self.available() or '<none>'}. "
            )
        return self._adapters[name]

    def available(self) -> List[str]:
        return sorted(self._adapters)

    def __contains__(self, name: str) -> bool:
        return name in self._adapters

    def __len__(self) -> int:
        return len(self._adapters)


registry = _Registry()

"""Real (non-offline) backends.

The ONLY place a heavy dependency is touched. Adapters call into here and, on
any :class:`BackendNotAvailable`, fall back to the offline artifact with the
error recorded in the manifest patch, so a run still completes and the reason
is auditable.

We target each tool's **documented stable surface**:

* Boltz-2   : ``boltz predict input.yaml -o dir`` (CLI; ``input_path`` is a
              positional arg; YAML job-list input is the documented format).
* Chai-1    : ``chai_lab`` import, FASTA input (documented on HF + PyPI).
* MPNN      : ``proteinmpnn --pdb-path backbone.pdb --out-folder out_dir`` —
              the entry point installed by ``pip install proteinmpnn`` (0.1.3,
              MIT). Emits ``predicted_sequence.jsonl`` with one sequence per
              line. Note: the repo's helper-script-style
              ``python -m proteinmpnn.reimpose`` does NOT exist in the pip
              package — do not call it.

Phase 2 (QM engines, all lazy, all optional):

* MACE      : ``mace-torch`` (ACEsuit/MACE, NeurIPS'22). Foundation model
              name via ``OPENSCIENCELAB_MACE_MODEL`` (default
              ``MACE-MP-0-medium``). ``ase.Atoms.calc = MACECalculator``.
* CHGNet    : ``ase.calculators.chgnet.CHGNet`` — Materials-Project-trained
              MPNN potential (arXiv 2007.12145).
* PySCF     : ``pyscf.gto.M`` + ``pyscf.dft.RKS`` — full DFT tier for small
              organics (the FEP+/CCSD(T) outer loop).

Geometry honesty note: for SMILES candidates we build a crude deterministic
2D scaffold layout (1.4 A spacing + small z jitter). That is NOT a real
conformer — any energy from it is a rank-ordering proxy, recorded as such in
the manifest patch and the artifact payload. Structure candidates
(Boltz/Chai/MPNN) carry real 3D coordinates and can be run through the same
backends directly.

That keeps us resilient to their frequent internal refactors, and every
command we run is visible in the manifest (we log the full argv on failure).
"""
from __future__ import annotations

import glob
import json
import os
import shutil
import subprocess
from typing import Any, Dict, List, Optional


class BackendNotAvailable(RuntimeError):
    """Real backend required but not usable. Adapters catch this -> offline."""


# --------------------------------------------------------------------------- #
# Device / GPU state                                                           #
# --------------------------------------------------------------------------- #
def torch_or_none():
    try:
        import torch  # type: ignore

        return torch
    except Exception:
        return None


def device() -> str:
    """Torch device string.

    ROCm exposes the CUDA device id (``"cuda"``); ``HSA_OVERRIDE_GFX_VERSION``
    handles the Strix Halo gfx1151 mapping at HSA-init. If the HSA runtime
    failed to attach, torch reports ``cuda.is_available() == False`` and we
    fall back to CPU *loudly*: the manifest patch from ``gpu_info()`` records
    why, so it's never silent. ``OPENSCIENCELAB_DEVICE`` may force
    ``cpu``/``cuda``; empty means auto.
    """
    ov = (os.environ.get("OPENSCIENCELAB_DEVICE") or "").lower()
    if ov in ("cpu", "cuda", "xpu", "mps"):
        return ov
    torch = torch_or_none()
    if torch is None:
        return "cpu"
    return "cuda" if torch.cuda.is_available() else "cpu"


def gpu_info() -> Dict[str, Any]:
    """Hardware snapshot for the manifest + the ``gpucheck`` CLI. Never raises."""
    torch = torch_or_none()
    info: Dict[str, Any] = {
        "torch": torch.__version__ if torch else None,
        "torch_hip": (
            str(torch.version.hip)
            if torch and getattr(torch.version, "hip", None)
            else None
        ),
        "torch_cuda": (
            str(torch.version.cuda)
            if torch and getattr(torch.version, "cuda", None)
            else None
        ),
        "cuda_visible": bool(torch and torch.cuda.is_available()),
        "device": device(),
        "HSA_OVERRIDE_GFX_VERSION": os.environ.get("HSA_OVERRIDE_GFX_VERSION"),
    }
    if torch and torch.cuda.is_available():
        try:
            info["device_name"] = torch.cuda.get_device_name(0)
            info["device_count"] = torch.cuda.device_count()
        except Exception:
            info["device_name"] = None
            info["device_count"] = 0
    return info


# --------------------------------------------------------------------------- #
# Boltz-2 — structure                                                          #
# --------------------------------------------------------------------------- #
def _norm_input(input_: Any) -> Dict[str, Any]:
    """Normalize ``seq``/``smi`` and ``sequence``/``smile`` to one shape."""
    if isinstance(input_, str):
        return {"name": "A", "sequence": input_}
    if isinstance(input_, dict):
        out: Dict[str, Any] = {"chains": [], "smile": None}
        if input_.get("sequence") or input_.get("seq"):
            out["chains"].append(
                {
                    "name": "A",
                    "sequence": input_.get("sequence") or input_.get("seq"),
                }
            )
        for c in input_.get("chains") or []:
            if not isinstance(c, dict):
                continue
            nc = {k: c.get(k) for k in ("name",) if c.get(k)}
            seq = c.get("sequence") or c.get("seq")
            smi = c.get("smile") or c.get("smi")
            if seq:
                nc["sequence"] = seq
            if smi:
                nc["smile"] = smi
            if nc.get("sequence") or nc.get("smile"):
                out["chains"].append(nc)
        out["smile"] = input_.get("smile") or input_.get("smi")
        return out
    raise TypeError(f"unsupported structure input type: {type(input_)!r}")


def _boltz_yaml(input_: Any, name: str) -> str:
    """Render our input (str sequence, or dict with chains + SMILES) into
    boltz's documented YAML job list."""
    import yaml  # pyyaml ships with boltz

    n = _norm_input(input_)

    job: Dict[str, Any] = {"name": name}
    proteins: List[Dict[str, str]] = []
    ligands: List[Dict[str, str]] = []

    for i, c in enumerate(n["chains"]):
        if c.get("smile"):
            ligands.append({"name": c.get("name") or f"lig{i}", "smile": c["smile"]})
        if c.get("sequence"):
            proteins.append({"name": c.get("name") or f"P{i}", "sequence": c["sequence"]})
    if n.get("smile"):
        ligands.append({"name": "lig", "smile": n["smile"]})

    if not proteins and not ligands:
        raise ValueError("no protein sequence or SMILES in input")
    if proteins:
        job["proteins"] = proteins
    if ligands:
        job["ligands"] = ligands
    return yaml.safe_dump([job], sort_keys=False)


def predict_boltz2(input_: Any, work_dir: str, name: str = "target") -> Dict[str, Any]:
    """Run ``boltz predict`` on ``input_`` into ``work_dir``.

    Returns ``{"predicted": <best CIF>, "metrics": {...}, "device": str,
    "output_root": <dir>}``. Raises :class:`BackendNotAvailable` on any failure.
    """
    os.makedirs(work_dir, exist_ok=True)
    yaml_path = os.path.join(work_dir, "input.yaml")
    with open(yaml_path, "w") as fh:
        fh.write(_boltz_yaml(input_, name))

    exe = shutil.which("boltz")
    if exe is None:
        raise BackendNotAvailable(
            "'boltz' not on PATH. In Docker it ships in the image; "
            "bare metal: pip install 'boltz>=2.0'"
        )
    cmd = [exe, "predict", yaml_path, "-o", work_dir]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
    except subprocess.TimeoutExpired as e:
        raise BackendNotAvailable("boltz predict timed out (>1h); cmd=" + " ".join(cmd)) from e
    if proc.returncode != 0:
        raise BackendNotAvailable(
            f"boltz predict exited {proc.returncode}: {proc.stderr[-2000:]}"
        )

    # boltz 2.x output: work_dir/predictions/<name>/{*_model_0.cif, confidence_*.json}
    target_dir = os.path.join(work_dir, "predictions", name)
    cifs = sorted(glob.glob(os.path.join(target_dir, "*_model_0.cif")))
    if not cifs:
        cifs = sorted(glob.glob(os.path.join(work_dir, "**", "*_model_0.cif"), recursive=True))
    if not cifs:
        raise BackendNotAvailable(
            f"boltz finished but no *_model_0.cif found under {work_dir!r}"
        )
    best = cifs[0]  # boltz ranks model_0 first

    metrics: Dict[str, float] = {}
    for conf in glob.glob(os.path.join(target_dir, "confidence_*.json")):
        try:
            with open(conf) as fh:
                for k, v in json.load(fh).items():
                    if isinstance(v, (int, float)) and not isinstance(v, bool):
                        metrics[k] = float(v)
        except Exception:
            pass
    return {
        "predicted": best,
        "metrics": metrics,
        "device": device(),
        "output_root": os.path.join(work_dir, "predictions"),
    }


# --------------------------------------------------------------------------- #
# Chai-1 — structure                                                           #
# --------------------------------------------------------------------------- #
def _chai1_fasta(input_: Any) -> str:
    n = _norm_input(input_)
    out = []
    for c in n["chains"]:
        if c.get("sequence"):
            out.append(f">{c.get('name') or 'A'}\n{c['sequence']}\n")
    if not out:
        raise ValueError("no protein sequence in input for chai1")
    return "".join(out)


def predict_chai1(input_: Any, out_dir: str) -> Dict[str, Any]:
    """Run Chai-1 ``chai_lab.chai1.run_inference`` on a FASTA.

    FASTA is chai1's documented input. We write it, call the documented API,
    then return the best PDB chai1 emitted.
    """
    os.makedirs(out_dir, exist_ok=True)
    fasta = os.path.join(out_dir, "input.fasta")
    with open(fasta, "w") as fh:
        fh.write(_chai1_fasta(input_))

    try:
        from chai_lab import chai1  # type: ignore
    except Exception as e:
        exe = shutil.which("chai1")
        if exe is None:
            raise BackendNotAvailable(
                f"chai1 not importable and no 'chai1' CLI (got {type(e).__name__})"
            ) from e
        cmd = [exe, "predict", fasta, "-o", out_dir]
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
        except subprocess.TimeoutExpired as e:
            raise BackendNotAvailable("chai1 timed out (>1h); cmd=" + " ".join(cmd)) from e
        if proc.returncode != 0:
            raise BackendNotAvailable(f"chai1 exited {proc.returncode}: {proc.stderr[-1500:]}")
        pdb = _find_best(out_dir)
        if pdb is None:
            raise BackendNotAvailable("chai1 finished but no PDB found in out_dir")
        return {"predicted": pdb, "metrics": {}, "device": device(), "output_root": out_dir}

    # Chai-1's import surface has moved across 0.4-0.7, so we try the
    # documented ``run_inference`` first, then fall through to the model
    # constructor if that surface is absent.
    try:
        kwargs: Dict[str, Any] = dict(
            device=device(),
            num_diffusion_iterations=100,
            num_trunk_iterations=1,
            checkpoint_dir=None,
        )
        pred = chai1.run_inference(fasta, out_dir=out_dir, **kwargs)
    except (AttributeError, TypeError) as e:
        raise BackendNotAvailable(
            f"chai1.run_inference signature changed ({type(e).__name__}: {e}); "
            "see chai-lab docs for the current kwarg set"
        ) from e
    except Exception as e:
        raise BackendNotAvailable(
            f"chai1 run_inference failed: {type(e).__name__}: {e}"
        ) from e

    pdb = _find_best(out_dir)
    if pdb is None:
        raise BackendNotAvailable("chai1 finished but no PDB found in out_dir")
    return {"predicted": pdb, "metrics": {}, "device": device(), "output_root": out_dir}


def _find_best(root: str) -> Optional[str]:
    """chai1 emits PDBs under out_dir/predictions/...; take the first,
    preferring anything with 'predicted' in the name."""
    peds = glob.glob(os.path.join(root, "**", "*.cif"), recursive=True)
    if not peds:
        peds = glob.glob(os.path.join(root, "**", "*.pdb"), recursive=True)
    peds.sort(key=lambda p: ("predicted" not in p.lower(), p))
    return peds[0] if peds else None


# --------------------------------------------------------------------------- #
# ProteinMPNN — design                                                         #
# --------------------------------------------------------------------------- #
def design_mpnn(backbone_pdb: str, out_dir: str, n_seqs: int = 3, seed: int = 0) -> List[Dict[str, str]]:
    """Re-impose sequences on a backbone via the proteinmpnn pip package (MIT).

    ``proteinmpnn==0.1.3`` installs a ``proteinmpnn`` entry point — NOT a
    ``python -m proteinmpnn...`` module (that module does not exist). Flags
    (documented in the PyPI description): ``--pdb-path`` /
    ``--out-folder`` / ``--num_seq_per_target`` / ``--seed`` /
    ``--temperature`` (sampling temperature). Output: a
    ``predicted_sequence.jsonl`` inside the out folder, one JSON object per
    entry with a ``"sequence"`` per chain. We collect up to ``n_seqs``
    sequences and the adapter's offline fallback tops the rest up
    deterministically when MPNN is unavailable.
    """
    if not os.path.exists(backbone_pdb):
        raise BackendNotAvailable(f"backbone PDB not found: {backbone_pdb!r}")
    exe = shutil.which("proteinmpnn")
    if exe is None:
        # fall back to "python -c 'from proteinmpnn import protein_mpnn_main; ...'"
        # is NOT documented; instead just report clearly so the offline path kicks in.
        raise BackendNotAvailable(
            "proteinmpnn entry point not on PATH; "
            "pip install proteinmpnn (>=0.1.3)"
        )
    os.makedirs(out_dir, exist_ok=True)
    # MPNN's seed default (0) means "random seed" — always pin one for us.
    cmd = [
        exe,
        "--pdb-path", backbone_pdb,
        "--out-folder", out_dir,
        "--num_seq_per_target", str(max(1, n_seqs)),
        "--seed", str(seed if seed else 1337),
    ]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=1800)
    except subprocess.TimeoutExpired as e:
        raise BackendNotAvailable("proteinmpnn timed out (>30m)") from e
    if proc.returncode != 0:
        raise BackendNotAvailable(
            f"proteinmpnn exited {proc.returncode}: {proc.stderr[-2000:]}"
        )
    # Output contract: "<out>/predicted_sequence.jsonl" (one JSON per line,
    # "sequence" per chain keyed by chain id). Scan rather than assume layout.
    lines: List[Dict[str, Any]] = []
    for name in ("predicted_sequence.jsonl",):
        for p in glob.glob(os.path.join(out_dir, "**", name), recursive=True):
            with open(p) as fh:
                for ln in fh:
                    ln = ln.strip()
                    if ln:
                        try:
                            lines.append(json.loads(ln))
                        except Exception:
                            continue
            break
    if not lines:
        raise BackendNotAvailable(
            f"proteinmpnn finished but no predicted_sequence.jsonl under {out_dir}"
        )
    out: List[Dict[str, str]] = []
    for i, d in enumerate(lines[: max(1, n_seqs)]):
        seqs = d.get("sequences") or d.get("sequence") or d
        if isinstance(seqs, dict):
            # per-chain dict {"A": "MSK...", "B": "..."} ; take the biggest chain
            best = max(seqs.items(), key=lambda kv: len(kv[1]))
            s = best[1]
        else:
            s = str(seqs)
        out.append({"name": f"MPNN-{i:03d}", "seq": s, "source": "proteinmpnn"})
    return out


# --------------------------------------------------------------------------- #
# Phase 2 — QM engines (MACE / CHGNet / PySCF)                                #
# --------------------------------------------------------------------------- #
_SYMBOL_TO_Z = {
    "C": 6, "N": 7, "O": 8, "F": 9, "P": 15, "S": 16, "Cl": 17,
    "Br": 35, "B": 5, "I": 53, "Li": 3, "Na": 11, "K": 19, "Mg": 12,
    "Ca": 20, "Zn": 30, "Mn": 25, "Fe": 26, "Cu": 29,
}
_HBA_ATOMS = ("O", "N", "S", "F", "Cl")


def _atom_tokens(smi: str) -> List[str]:
    """Crude SMILES tokenizer: heavy-atom symbols in order. This is the
    canonical SMILES-lite path; ``adapters.scoring`` re-exports it for
    tier-0 descriptors (no duplicated implementation anywhere else)."""
    if not smi:
        return []
    smi = (smi.replace("(", "").replace(")", "").replace("=", "")
              .replace("#", "").replace("-", "").replace("/", "").replace("\\", ""))
    out: List[str] = []
    i = 0
    smap = {"n": "N", "o": "O", "s": "S", "p": "P", "f": "F", "b": "B", "c": "C"}
    while i < len(smi):
        ch = smi[i]
        if ch.isalpha():
            if ch.isupper():
                if smi[i:i + 2] in ("Cl", "Br"):
                    out.append(smi[i:i + 2])
                    i += 2
                    continue
                out.append(ch)
            else:
                out.append(smap.get(ch, ch))
        i += 1
    return out


def element_types_of(smi: str) -> List[int]:
    """Atom numbers from a SMILES. Prefers RDKit (accurate); falls back to the
    SMILES-lite tokenizer above (no dependency)."""
    try:
        from rdkit import Chem  # type: ignore

        mol = Chem.MolFromSmiles(smi)
        if mol is not None and next(iter(mol.GetAtoms()), None) is not None:
            return [a.GetAtomicNum() for a in mol.GetAtoms()]
    except Exception:
        pass
    tokens = _atom_tokens(smi)
    if not tokens:
        raise BackendNotAvailable(f"unparseable SMILES: {smi!r}")
    return [_SYMBOL_TO_Z.get(t, 6) for t in tokens]


def scaffold_coords(numbers: List[int], seed: int = 7) -> List[List[float]]:
    """Deterministic placeholder 2D layout (1.4 A steps, small z jitter).

    NOT a conformer — energies on this are a rank-ordering proxy. Always
    prefer real structure output (Boltz-2 / Chai-1 / MPNN backbones) when
    available; pass its coordinates straight to :func:`mace_energy` /
    :func:`chgnet_energy` / :func:`pyscf_energy` instead."""
    import random

    rng = random.Random(seed)
    step = 1.4  # rough C-C bond length
    coords: List[List[float]] = []
    for i in range(len(numbers)):
        x = i * step + rng.uniform(-0.02, 0.02)
        y = 0.3 if (i % 2 == 0) else -0.3
        z = 0.05 if (i % 3 == 0) else -0.05
        coords.append([x, y, z])
    return coords


def _mace_device_str(device: Optional[str]) -> str:
    """Map our device() result onto MACE's expected string (MACE takes
    'cuda:0' style or 'cpu')."""
    if not device or device in ("cpu", "auto"):
        return "cpu"
    if device == "cuda":
        try:
            import torch
            return "cuda:0" if torch.cuda.is_available() else "cpu"
        except Exception:
            return "cuda:0"
    return device  # already specific, e.g. 'cuda:1' or 'mps'


def _mace_calc_factory(device: Optional[str] = None):
    """Build an ASE-compatible MACE calculator for the configured foundation
    model. Tries, in order:

    1. ``mace.calculators.mace_mp()`` — the documented foundation-model
       loader in mace-torch >= 0.3 (returns a ready :class:`MACECalculator`;
       pick the model via ``OPENSCIENCELAB_MACE_MODEL``).
    2. Legacy ``mace.load_model(name)`` + :class:`MACECalculator` wrap.

    Failures raise :class:`BackendNotAvailable` with the underlying cause.
    """
    dev = _mace_device_str(device)
    try:
        from mace.calculators import MACECalculator  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"mace.calculators import failed: {e}")

    name = os.environ.get("OPENSCIENCELAB_MACE_MODEL") or "MACE-MP-0-medium"

    # 1) foundation-model convenience loader: mace_mp(device=..., model_name=...)
    #    (mace-torch >= 0.3). Older builds used positional name only — fall
    #    through to the legacy path if the kwarg name doesn't match.
    try:
        from mace.calculators import mace_mp  # type: ignore

        try:
            calc = mace_mp(device=dev, model_name=name)
        except TypeError:
            try:
                calc = mace_mp(name, device=dev)
            except TypeError:
                calc = mace_mp(device=dev)
        return calc, "mace_mp"
    except Exception:
        pass

    # 2) legacy path
    try:
        import mace  # type: ignore

        model = mace.load_model(name)
        return MACECalculator(model=model, devices=dev), f"mace[{name}]"
    except Exception as e:
        raise BackendNotAvailable(f"no working MACE loader (tried mace_mp + legacy): {e}")


_MACE_CALC_CACHE: Dict[str, Any] = {}


def mace_energy(coords: List[List[float]], numbers: List[int],
                device: Optional[str] = None) -> Dict[str, Any]:
    """MACE potential energy in eV (forces included free — single ASE pass)."""
    try:
        import ase  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"ase import failed: {e}")
    key = device or "cpu"
    if key not in _MACE_CALC_CACHE:
        _MACE_CALC_CACHE[key] = _mace_calc_factory(device)
    calc, label = _MACE_CALC_CACHE[key]
    atoms = ase.Atoms(numbers=list(numbers), positions=list(coords))
    atoms.calc = calc
    try:
        energy = float(atoms.get_potential_energy())
        forces = atoms.get_forces().tolist()
    except Exception as e:
        raise BackendNotAvailable(f"MACE inference failed: {e}")
    return {"energy_eV": energy, "forces": forces, "model": label,
            "device": _mace_device_str(device)}


def mace_available() -> bool:
    try:
        import mace.calculators  # noqa: F401
        return True
    except Exception:
        return False


def chgnet_available() -> bool:
    try:
        import ase  # noqa: F401
        from ase.calculators.chgnet import CHGNet  # noqa: F401
        return True
    except Exception:
        return False


def chgnet_energy(coords: List[List[float]], numbers: List[int]) -> Dict[str, Any]:
    """CHGNet (ASE) total energy in eV + forces."""
    try:
        import ase  # type: ignore
        from ase.calculators.chgnet import CHGNet  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"CHGNet / ase import failed: {e}")
    atoms = ase.Atoms(numbers=list(numbers), positions=list(coords))
    try:
        atoms.calc = CHGNet()
        energy = float(atoms.get_total_energy())
        forces = atoms.get_forces().tolist()
    except Exception as e:
        raise BackendNotAvailable(f"CHGNet inference failed: {e}")
    return {"energy_eV": energy, "forces": forces, "model": "CHGNet", "device": "cpu"}


def pyscf_available() -> bool:
    try:
        import pyscf  # noqa: F401
        return True
    except Exception:
        return False


def pyscf_energy(numbers: List[int], coords: List[List[float]],
                 xc: Optional[str] = None, basis: str = "6-31G*") -> Dict[str, Any]:
    """PySCF total electronic energy (Hartree).

    ``xc=None`` → RHF; else RKS with that functional (default recommended for
    Tier-2 DFT is B3LYP). ``basis`` defaults to 6-31G* — the canonical
    organic-molecule DFT basis.
    """
    try:
        import pyscf  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"pyscf import failed: {e}")
    atom_arg = [
        (int(n), (float(x), float(y), float(z)))
        for n, (x, y, z) in zip(numbers, coords)
    ]
    try:
        mol = pyscf.gto.M(atom=atom_arg, unit="Angstrom", basis=basis)
        if xc:
            mf = pyscf.dft.RKS(mol, xc=xc)
        else:
            mf = pyscf.hf.RHF(mol)
        e_total = mf.kernel()
    except Exception as e:
        raise BackendNotAvailable(f"pyscf kernel failed: {e}")
    return {
        "energy_Hartree": float(e_total),
        "method": f"{'RKS/' + xc if xc else 'RHF'}/{basis}",
    }


