def chgnet_energy(coords: List[List[float]], numbers: List[int]) -> Dict[str, Any]:
    """CHGNet (ASE) total energy in eV + forces."""
    try:
        import ase  # type: ignore
        from ase.calculators.chgnet import CHGNet  # type: ignore
    except Exception as e:
        raise BackendNotAvailable(f"CHGNet / ase import failed: {e}")
    atoms = ase.Atoms(numbers=list(numbers), positions=list(coords))
