"""Shared types, the Adapter contract, and the registry.

Design rule: every capability (structure, design, scoring, optimization) is an
:class:`Adapter`. Everything funnels through :meth:`Adapter.run`, which
charges the budget, stamps artifacts, and records the call on the run
manifest. That single choke point is what makes provenance and budgeting
trivial.

Re-exports from :mod:`.manifest` (``Budget``, ``budget_default``,
``BudgetExceeded``) so a service can import one module.
"""
from __future__ import annotations

import hashlib
import json
import time
import uuid
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from typing import Any, Dict, List, Optional

from .manifest import Budget, BudgetExceeded, Manifest, RunDirectory, budget_default  # noqa: F401  (re-export)


def _now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


# --------------------------------------------------------------------------- #
# Cost model: tiered compute                                                  #
# --------------------------------------------------------------------------- #
# Higher tier = slower / more expensive, used on fewer candidates. Costs are
# abstract "units" (not $); a Budget maps them to real cost as needed.
TIER_ZERO, TIER_ONE, TIER_TWO = 0, 1, 2


# --------------------------------------------------------------------------- #
# Core data types                                                             #
# --------------------------------------------------------------------------- #
@dataclass
class Candidate:
    """A thing being scored (molecule / complex / crystal)."""

    id: str
    kind: str = "molecule"  # molecule | complex | crystal
    smi: Optional[str] = None
    pdb_id: Optional[str] = None
    seq: Optional[str] = None
    metadata: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "Candidate":
        d = dict(d)
        d.setdefault("metadata", {})
        allowed = {k: d[k] for k in ("id", "kind", "smi", "pdb_id", "seq", "metadata") if k in d}
        return cls(**allowed)


@dataclass
class ScoreVector:
    """Named metric values for a candidate.

    Convention: **higher is better** for every key. A scoring adapter flips the
    sign of naturally "lower-better" metrics (e.g. docking energy) beforehand.
    """

    metrics: Dict[str, float] = field(default_factory=dict)
    tier: int = TIER_ZERO
    notes: Dict[str, Any] = field(default_factory=dict)

    def get(self, name: str, default: float = 0.0) -> float:
        return self.metrics.get(name, default)

    def to_dict(self) -> Dict[str, Any]:
        return {"tier": self.tier, "metrics": self.metrics, "notes": self.notes}

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "ScoreVector":
        return cls(
            metrics=dict(d.get("metrics", {})),
            tier=d.get("tier", TIER_ZERO),
            notes=dict(d.get("notes", {})),
        )


@dataclass
class Artifact:
    """An immutable product of an adapter call, with a stable digest."""

    id: str = ""
    kind: str = ""  # structure | design_seqs | scores | pareto | report | ...
    service: str = ""
    service_version: str = ""
    created_at: str = ""
    payload: Dict[str, Any] = field(default_factory=dict)
    files: List[str] = field(default_factory=list)  # relative paths under run dir

    def digest(self) -> str:
        blob = json.dumps(
            {
                "id": self.id,
                "kind": self.kind,
                "service": self.service,
                "service_version": self.service_version,
                "payload": self.payload,
            },
            sort_keys=True,
            default=str,
        ).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()[:16]

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["digest"] = self.digest()
        return d


@dataclass
class Bundle:
    """What every adapter returns: artifacts, manifest patch, cost by tier."""

    artifacts: List[Artifact] = field(default_factory=list)
    manifest_patch: Dict[str, Any] = field(default_factory=dict)
    cost: Dict[int, float] = field(
        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}
    )

    def total_cost(self) -> float:
        return sum(self.cost.values())


# --------------------------------------------------------------------------- #
# Adapter contract                                                            #
# --------------------------------------------------------------------------- #
class Adapter(ABC):
    """Base class for all services.

    Subclasses set ``name`` and ``version`` and implement :meth:`_exec`.
    :meth:`run` adds the boilerplate: charging the budget, stamping artifacts,
    and recording the call against the run manifest.
    """

    name: str = "adapter"
    version: str = "0.0.1"

    @abstractmethod
    def _exec(self, manifest, budget, **inputs) -> Bundle:
        raise NotImplementedError

    def run(self, manifest, budget, **inputs) -> Bundle:
        bundle = self._exec(manifest, budget, **inputs)

        # charge the budget for each tier used (validates per-tier limits)
        if budget is not None:
            for tier, cost in bundle.cost.items():
                budget.spend(int(tier), float(cost))

        # stamp artifacts with this service's identity
        for art in bundle.artifacts:
            if not art.service:
                art.service = self.name
            if not art.service_version:
                art.service_version = self.version
            if not art.created_at:
                art.created_at = _now()
            if not art.id:
                art.id = new_id(art.kind)
            manifest.attach_artifact(art.to_dict(), list(art.files))

        # record the call (stable signature enables drift detection)
        manifest.record(
            service=self.name,
            version=self.version,
            call={k: _jsonable(v) for k, v in inputs.items()},
            cost=bundle.cost,
            artifacts=[a.id for a in bundle.artifacts],
        )
        manifest.merge_patch(bundle.manifest_patch)
        return bundle


def _jsonable(v: Any) -> Any:
    if isinstance(v, dict):
        return {str(k): _jsonable(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        return [_jsonable(x) for x in v]
    if isinstance(v, (str, int, float, bool)) or v is None:
        return v
    if isinstance(v, Candidate):
        return v.to_dict()
    if isinstance(v, ScoreVector):
        return v.to_dict()
    return repr(v)


def new_id(prefix: str) -> str:
    return f"{prefix}-{uuid.uuid4().hex[:10]}"


# --------------------------------------------------------------------------- #
# Registry                                                                    #
# --------------------------------------------------------------------------- #
class _Registry:
    """Name -> Adapter instance. Adapters self-register on import."""

    def __init__(self) -> None:
        self._adapters: Dict[str, Adapter] = {}

    def register(self, adapter: Adapter) -> None:
        existing = self._adapters.get(adapter.name)
        if existing is not None and existing.version != adapter.version:
            raise ValueError(
                f"adapter {adapter.name!r} already registered at "
                f"{existing.version!r}; refusing to overwrite"
            )
        self._adapters[adapter.name] = adapter

    def get(self, name: str) -> Adapter:
        if name not in self._adapters:
            raise KeyError(
                f"adapter {name!r} not registered. "
                f"Available: {self.available() or '<none>'}. "
            )
        return self._adapters[name]

    def available(self) -> List[str]:
        return sorted(self._adapters)

    def __contains__(self, name: str) -> bool:
        return name in self._adapters

    def __len__(self) -> int:
        return len(self._adapters)


registry = _Registry()
